questionvariables.text:
/*Defining the question variables*/ 
coef1:rand(9)+1;/*coeffient of the function*/
const:rand(4)+1;/* constant inside the function*/
lower_y:rand(5)+2;/*lower lmit of y*/
upper_y:rand(3)+lower_y+2;/*upper lmit of y*/
aa:1/(2*coef1); /*coeff of tan*/
functy: coef1*(const+y)^(2);/*function of y*/
expr:f(y)=coef1*(const+y)^(2); /*the function*/
dx:rhs(diff(expr)/del(y)); /*dx/dy*/
ds:sqrt(1+(dx)^2);
func:y=(1/(2*coef1))*tan(theta)-const;   /*function of y*/
diff_func:diff(rhs(func),theta); /*derivative of y*/
/*new limits of theta*/
theta1:ev(func,y=lower_y);
theta_1:solve(theta1,theta)[1];
rhs_theta_1:rhs(theta_1);   dd: rhs_theta_1;     
theta2:ev(func,y=upper_y);
theta_2:solve(theta2,theta)[1];
rhs_theta_2:rhs(theta_2);   bb:rhs_theta_2;
inty:int(ds,y);

/*Model answers*/
arc_length:decimalplaces(float(int(ds,y,lower_y,upper_y)),2);
ta:float(int(sec(theta)^3,theta,rhs_theta_1,rhs_theta_2));
ta_1:decimalplaces(aa*ta,2);

feedbackvariables.text:
/*Node 1 checks for correct answer*/
/*Node 2: mistake:Integrating the expression instead of differentiating*/
mistake_2:rhs((int(expr,y)));
/*Node 3: mistake:   Interchanging the limits of integration*/
mistake_1:int(ds,yrhs_y2,rhs_y1);
mistake_2:decimalplaces(float(mistake_1),3);
